};
console.log(JSON.stringify({ source_count: sources.length, pool_count: pool.opportunities.length, public_procurement: publicItems.length, gates }, null, 2));
')"
  QUALITY_RESULT="$quality_result" RUN_NAME="$audit_name" node - <<'NODE'
const fs = require('fs');
const result = JSON.parse(process.env.QUALITY_RESULT || '{}');
const gates = result.gates || {};
const failed = Object.entries(gates).filter(([, value]) => value !== 0);
fs.writeFileSync(`${process.env.BACKUP_ROOT}/${process.env.RUN_NAME}-quality.json`, JSON.stringify(result, null, 2));
