NODE
}

cross_source_dedup_audit() {
  (cd "$CURRENT_LINK" && "$CURRENT_LINK/node_modules/.bin/tsx" -e '
import fs from '"'"'node:fs'"'"';
import { deduplicateOpportunityV2, readOpportunityV2Pool } from '"'"'./src/opportunity-v2'"'"';
const pool = readOpportunityV2Pool(process.env.OPPORTUNITIES_PATH);
const required = new Set(['"'"'proc-uk-fts'"'"', '"'"'proc-ca-canadabuys'"'"', '"'"'proc-cn-ccgp'"'"', '"'"'proc-cn-cib'"'"', '"'"'proc-global-ocp'"'"', '"'"'proc-eu-ted'"'"', '"'"'proc-wb'"'"']);
const auditedRows = pool.opportunities.filter((row) => row.category === '"'"'procurement_project'"'"' || required.has(row.source_id) || row.discovered_by_sources.some((sourceId) => required.has(sourceId)));
const deduped = deduplicateOpportunityV2(auditedRows);
const merged = auditedRows.filter((row) => new Set((row.discovered_by_sources || []).filter((sourceId) => required.has(sourceId))).size > 1).map((row) => ({ id: row.id, discovered_by_sources: row.discovered_by_sources }));
const result = { sources_audited: [...new Set([...required, ...auditedRows.map((row) => row.source_id).filter(Boolean)])].sort(), audited_rows: auditedRows.length, duplicate_public_cards: auditedRows.length - deduped.opportunities.length, merged_discovered_by_sources: merged, canonical_duplicate_count: deduped.duplicate_count };
fs.writeFileSync(process.env.BACKUP_ROOT + '"'"'/cross-source-dedup.json'"'"', JSON.stringify(result, null, 2));
console.log(JSON.stringify(result));
if (result.duplicate_public_cards !== 0 || result.canonical_duplicate_count !== 0) throw new Error('"'"'cross-source dedup failed: '"'"' + JSON.stringify(result));
')
}

capture_pool_identities() {
  local run_name="$1"
  RUN_NAME="$run_name" node - <<'NODE'
const fs = require('fs');
const path = process.env.OPPORTUNITIES_PATH;
const parsed = JSON.parse(fs.readFileSync(path, 'utf8'));
const rows = Array.isArray(parsed) ? parsed : (parsed.opportunities || []);
function normalizedUrl(value) {
  if (!value) return '';
  try { const url = new URL(value); url.hash = ''; return `${url.protocol}//${url.host}${url.pathname.replace(/\/+$/u, '')}${url.search}`.toLowerCase(); } catch { return String(value).trim().replace(/\/+$/u, '').toLowerCase(); }
}
function stableKey(row) { return `${row.source_id || ''}|${row.source_item_id || normalizedUrl(row.detail_url) || row.id || ''}`; }
const identities = rows.map((row) => ({ id: row.id, source_id: row.source_id, source_item_id: row.source_item_id || null, detail_url: row.detail_url || null, stable_key: stableKey(row), first_seen_at: row.first_seen_at || null, last_seen_at: row.last_seen_at || null, discovered_by_sources: Array.isArray(row.discovered_by_sources) ? [...row.discovered_by_sources] : [] }));
fs.writeFileSync(`${process.env.BACKUP_ROOT}/${process.env.RUN_NAME}-identities.json`, JSON.stringify({ run: process.env.RUN_NAME, count: identities.length, source_item_ids: identities.map((row) => row.source_item_id).filter(Boolean), identities }, null, 2));
NODE
}

compare_run_idempotency() {
  node - <<'NODE'
const fs = require('fs');
const first = JSON.parse(fs.readFileSync(`${process.env.BACKUP_ROOT}/run_1-identities.json`, 'utf8')).identities || [];
const second = JSON.parse(fs.readFileSync(`${process.env.BACKUP_ROOT}/run_2-identities.json`, 'utf8')).identities || [];
const secondByKey = new Map(second.map((row) => [row.stable_key, row]));
const missingStableIds = first.filter((row) => !secondByKey.has(row.stable_key));
const firstSeenPreserved = first.every((row) => secondByKey.get(row.stable_key)?.first_seen_at === row.first_seen_at);
const lastSeenSafe = first.every((row) => { const next = secondByKey.get(row.stable_key); return !next || !row.last_seen_at || !next.last_seen_at || new Date(next.last_seen_at).getTime() >= new Date(row.last_seen_at).getTime(); });
const discoveredBySourcesMergeSafe = first.every((row) => { const next = secondByKey.get(row.stable_key); const before = new Set(row.discovered_by_sources); return next && [...before].every((sourceId) => next.discovered_by_sources.includes(sourceId)); });
const duplicateOpportunitiesCreated = second.length - new Set(second.map((row) => row.stable_key)).size;
const result = { missing_stable_ids: missingStableIds.map((row) => row.stable_key), duplicate_opportunities_created: duplicateOpportunitiesCreated, same_source_stable_ids: missingStableIds.length === 0, first_seen_at_preserved: firstSeenPreserved, last_seen_at_safe: lastSeenSafe, discovered_by_sources_safe: discoveredBySourcesMergeSafe, discovered_by_sources_merge_safe: discoveredBySourcesMergeSafe };
fs.writeFileSync(`${process.env.BACKUP_ROOT}/run-2-idempotency.json`, JSON.stringify(result, null, 2));
if (missingStableIds.length || duplicateOpportunitiesCreated || !firstSeenPreserved || !lastSeenSafe || !discoveredBySourcesMergeSafe) throw new Error(`run2 idempotency failed: ${JSON.stringify(result)}`);
console.log(JSON.stringify(result));
NODE
}

assert_phase1_stable_state() {
  local phase_name="$1"
  assert_ready_core_state "$phase_name"
  PHASE_NAME="$phase_name" node - <<'NODE'
const fs = require('fs');
const read = (name) => JSON.parse(fs.readFileSync(`${process.env.BACKUP_ROOT}/${name}`, 'utf8'));
const quality = ['run-1-quality.json', 'run-2-quality.json'].map((name) => ({ name, value: read(name) }));
const qualityFailures = quality.flatMap(({ name, value }) => Object.entries(value.gates || {}).filter(([, count]) => count !== 0).map(([gate, count]) => `${name}:${gate}=${count}`));
const idempotency = read('run-2-idempotency.json');
const dedup = read('cross-source-dedup.json');
const regression = read('competition-memo-regression.json');
const result = { phase: process.env.PHASE_NAME, quality_failures: qualityFailures, duplicate_opportunities: idempotency.duplicate_opportunities_created, canonical_duplicates: dedup.canonical_duplicate_count, first_seen_at_preserved: idempotency.first_seen_at_preserved, discovered_by_sources_safe: idempotency.discovered_by_sources_safe, competition_unexplained_loss: regression.competition_unexplained_loss, memo_unexplained_loss: regression.memo_unexplained_loss, memo_parity: regression.memo_parity, loewe_preserved: regression.loewe_preserved };
if (qualityFailures.length || idempotency.duplicate_opportunities_created !== 0 || !idempotency.first_seen_at_preserved || !idempotency.discovered_by_sources_safe || dedup.duplicate_public_cards !== 0 || dedup.canonical_duplicate_count !== 0 || regression.competition_unexplained_loss.length || regression.memo_unexplained_loss.length || !regression.memo_parity.json_html || !regression.memo_parity.json_markdown || regression.memo_parity.duplicate_ids || !regression.loewe_preserved) throw new Error(`final stable gate failed: ${JSON.stringify(result)}`);
console.log(JSON.stringify(result));
NODE
}

rollback() {
  local reason="$1"
  local rollback_failure="rollback failed: $reason"
  local rollback_failed=0
  trap - ERR
  set +e
  if [ "$backup_ready" != "1" ]; then
    rollback_failed=1
  else
    if systemctl is-active "$OP_SERVICE" --quiet; then
      systemctl stop "$OP_SERVICE" || rollback_failed=1
    fi
    restore_runtime_file "$SOURCES_PATH" "$BACKUP_SOURCE_BACKUP" || rollback_failed=1
    restore_runtime_file "$OPPORTUNITIES_PATH" "$BACKUP_POOL_BACKUP" || rollback_failed=1
    restore_runtime_file "$SOURCE_HEALTH_PATH" "$BACKUP_HEALTH_BACKUP" || rollback_failed=1
    restore_runtime_file "$SCHEDULER_PATH" "$BACKUP_SCHEDULER_BACKUP" || rollback_failed=1
    if [ -z "$previous_release" ] || [ ! -d "$previous_release" ]; then
      rollback_failed=1
      rollback_failure="release restore failed"
    else
      ln -sfn "$previous_release" "$CURRENT_LINK" || { rollback_failed=1; rollback_failure="release restore failed"; }
      if [ "$(readlink -f "$CURRENT_LINK")" != "$previous_release" ]; then
        rollback_failed=1
        rollback_failure="release restore failed"
      fi
    fi
    restore_runtime_file "$RELEASE_MANIFEST" "$BACKUP_MANIFEST" || { rollback_failed=1; rollback_failure="release manifest restore failed"; }
    systemctl restart "$SERVICE_NAME" || { rollback_failed=1; rollback_failure="chanceping.service restart failed"; }
    verify_all_restored_runtime || { rollback_failed=1; rollback_failure="restored runtime checksum mismatch"; }
    run_http "$BASE_URL/health" || { rollback_failed=1; rollback_failure="/health verification failed"; }
    run_http "$BASE_URL/ich" || { rollback_failed=1; rollback_failure="/ich verification failed"; }
  fi
  restore_timer_state || { rollback_failed=1; rollback_failure="timer restore failed"; }
  verify_timer_state || { rollback_failed=1; rollback_failure="timer state verification failed"; }
  if [ "$rollback_failed" -ne 0 ]; then
    write_audit ROLLBACK_FAILED "$rollback_failure"
    exit 1
  fi
  write_audit ROLLED_BACK "rollback completed: $reason"
  exit 1
}

trap 'rollback "ERR trap"' ERR

# ----- Phase A: preflight -----
if [ -L "$CURRENT_LINK" ]; then
  previous_release="$(readlink -f "$CURRENT_LINK")"
fi
runtime_before_commit="$(git -C "$RUN_REPO_DIR" rev-parse HEAD)"
systemctl is-enabled "$TIMER_NAME" --quiet && timer_before_enabled=1 || timer_before_enabled=0
systemctl is-active "$TIMER_NAME" --quiet && timer_before_active=1 || timer_before_active=0
systemctl is-active "$OP_SERVICE" --quiet && op_service_before_active=1 || op_service_before_active=0
run_http "$BASE_URL/health"

# ----- Phase B: freeze timer and wait for scheduler quiescence -----
systemctl stop "$TIMER_NAME"
quiesce_deadline=$((SECONDS + QUIESCE_TIMEOUT_SECONDS))
while systemctl is-active "$OP_SERVICE" --quiet; do
  if (( SECONDS >= quiesce_deadline )); then
    echo "scheduler did not become inactive within ${QUIESCE_TIMEOUT_SECONDS}s; stopping rollout before deploy" >&2
    restore_timer_state
    trap - ERR
    exit 1
  fi
  sleep 2
done

# ----- Phase C: runtime backup and read-only snapshot -----
backup_runtime_file "$SOURCES_PATH" sources.json
backup_runtime_file "$OPPORTUNITIES_PATH" opportunities.json
backup_runtime_file "$SOURCE_HEALTH_PATH" source-health.json
backup_runtime_file "$SCHEDULER_PATH" scheduler.json
backup_runtime_file "$RELEASE_MANIFEST" release-manifest.json
backup_ready=1
capture_optional_json "$BASE_URL/api/opportunity-v2/radar" "$BACKUP_ROOT/public-radar-before.json"
capture_optional_json "$BASE_URL/ich/memo.json" "$BACKUP_ROOT/public-memo-before.json"
collect_snapshot
write_audit STAGED "preflight complete"

# ----- Phase C/D: exact target resolved and release deploy -----
git -C "$RUN_REPO_DIR" fetch --no-tags origin "$DEPLOY_TAG"
deploy_commit="$(git -C "$RUN_REPO_DIR" rev-parse --verify 'FETCH_HEAD^{commit}')"
if [ "$deploy_commit" != "$EXPECTED_COMMIT" ]; then
  rollback "deploy commit mismatch: $deploy_commit"
fi
helper=$(mktemp -t chanceping-release-proc-phase1.XXXXXX.sh)
git -C "$RUN_REPO_DIR" show "$deploy_commit:scripts/deploy-release.sh" > "$helper"
chmod 700 "$helper"
CHANCEPING_SERVER_REPO_DIR="$RUN_REPO_DIR" bash "$helper" "$deploy_commit"
rm -f "$helper"

run_http "$BASE_URL/health"
run_http "$BASE_URL/ich"
run_http "$BASE_URL/ich/memo"
run_http "$BASE_URL/ich/memo.json"
run_http "$BASE_URL/ich/memo.md"
run_http "$BASE_URL/api/opportunity-v2/radar"
run_http "$BASE_URL/api/opportunity-v2/sources"
run_http "$BASE_URL/opportunity-v2/admin/sources"

if [ ! -f "$RUN_REPO_DIR/release-manifest.json" ]; then
  rollback "release-manifest missing after deploy"
fi
node - <<'NODE'
const fs = require('fs');
const path = `${process.env.RUN_REPO_DIR}/release-manifest.json`;
const manifest = JSON.parse(fs.readFileSync(path, 'utf8'));
if (!manifest || manifest.commit !== process.env.EXPECTED_COMMIT) {
  process.exit(1);
}
NODE

# ----- Phase F: persistent migration ----
migration_result="$(cd "$CURRENT_LINK" && "$CURRENT_LINK/node_modules/.bin/tsx" -e 'import { DEFAULT_OPPORTUNITY_V2_SOURCES, migrateOpportunityV2Sources } from "./src/opportunity-v2"; const result = migrateOpportunityV2Sources(process.env.SOURCES_PATH); console.log(JSON.stringify({ before_count: result.before_count, after_count: result.after_count, added_ids: result.added_ids, default_source_ids: DEFAULT_OPPORTUNITY_V2_SOURCES.map((source) => source.id) }));')"
MIGRATION_RESULT="$migration_result" node - <<'NODE'
const fs = require('fs');
function readSources(filePath) {
  const parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  const sources = Array.isArray(parsed) ? parsed : parsed.sources;
  if (!Array.isArray(sources)) throw new Error(`invalid source registry: ${filePath}`);
  return sources;
}
const before = readSources(process.env.BACKUP_SOURCE_BACKUP);
const after = readSources(process.env.SOURCES_PATH);
const beforeIds = new Set(before.map((source) => source.id));
const afterIds = new Set(after.map((source) => source.id));
const missing = [...beforeIds].filter((id) => !afterIds.has(id));
const added = [...afterIds].filter((id) => !beforeIds.has(id));
const migration = JSON.parse(process.env.MIGRATION_RESULT || '{}');
const defaultSourceIds = Array.isArray(migration.default_source_ids) ? migration.default_source_ids : [];
const expectedAdded = defaultSourceIds.filter((id) => !beforeIds.has(id));
const unexpectedAdded = added.filter((id) => !defaultSourceIds.includes(id));
if (missing.length > 0) throw new Error(`source membership loss: ${missing.join(', ')}`);
if (unexpectedAdded.length > 0) throw new Error(`unexpected added source ids: ${unexpectedAdded.join(', ')}`);
if (JSON.stringify(added.sort()) !== JSON.stringify(expectedAdded.sort())) throw new Error(`migration added ids mismatch: ${JSON.stringify(added)}`);
for (const id of ['proc-cn-ccgp', 'proc-cn-cib', 'proc-global-ocp', 'proc-eu-ted', 'proc-wb']) {
  const source = after.find((candidate) => candidate.id === id);
  if (!source) throw new Error(`source missing: ${id}`);
  if (source.enabled !== false || source.status !== 'PENDING') throw new Error(`invalid procurement canary state for ${id}`);
}
if (migration.before_count !== before.length || migration.after_count !== after.length) throw new Error('migration report does not match persisted registry');
console.log(JSON.stringify({ before_count: before.length, after_count: after.length, added_ids: added, source_membership_loss: missing, unexpected_added_source_ids: unexpectedAdded }));
NODE

write_audit MIGRATED "source migration applied"

if [ "$CANARY_ENABLED" = "1" ]; then
  run_canary_pass pass1
  assert_ready_core_state run1
  # ----- Run 1 production quality gate -----
  run_production_quality_gate run1
  capture_pool_identities run_1
  run_http "$BASE_URL/api/opportunity-v2/radar"
  run_canary_pass pass2
  assert_ready_core_state run2
  # ----- Run 2 production quality gate -----
  run_production_quality_gate run2
  capture_pool_identities run_2
  compare_run_idempotency
  cross_source_dedup_audit
  capture_postdeploy_public
  compare_public_regression
  assert_phase1_stable_state pre-restore
fi

# ----- restore timer according to original enabled and active states -----
restore_timer_state
verify_timer_state
sleep 1
if systemctl is-active "$OP_SERVICE" --quiet; then
  post_restore_deadline=$((SECONDS + QUIESCE_TIMEOUT_SECONDS))
  while systemctl is-active "$OP_SERVICE" --quiet; do
    if (( SECONDS >= post_restore_deadline )); then
      echo "persistent timer-triggered scheduler did not become inactive" >&2
      false
    fi
    sleep 2
  done
  run_http "$BASE_URL/health"
  run_production_quality_gate post-restore
  capture_postdeploy_public
  compare_public_regression
fi

assert_phase1_stable_state final

trap - ERR
write_audit STABLE "rollout completed"
cat "$AUDIT_FILE"
